            "01": "https://cdn.equran.id/audio-partial/Abdullah-Al-Juhany/019040.mp3",
            "02": "https://cdn.equran.id/audio-partial/Abdul-Muhsin-Al-Qasim/019040.mp3",
            "03": "https://cdn.equran.id/audio-partial/Abdurrahman-as-Sudais/019040.mp3",
            "04": "https://cdn.equran.id/audio-partial/Ibrahim-Al-Dossari/019040.mp3",
