            "01": "https://cdn.equran.id/audio-partial/Abdullah-Al-Juhany/019044.mp3",
            "02": "https://cdn.equran.id/audio-partial/Abdul-Muhsin-Al-Qasim/019044.mp3",
            "03": "https://cdn.equran.id/audio-partial/Abdurrahman-as-Sudais/019044.mp3",
